(function(){"use strict";const toggle=document.querySelector(".mobile-menu-toggle");const nav=document.querySelector(".main-nav");if(toggle&&nav){const navLinks=nav.querySelectorAll("a");function setMenuOpen(open){toggle.classList.toggle("active",open);nav.classList.toggle("active",open);toggle.setAttribute("aria-expanded",String(open));if(open&&navLinks[0]){navLinks[0].focus()}else if(!open){toggle.focus()}}toggle.addEventListener("click",function(){const isOpen=nav.classList.contains("active");setMenuOpen(!isOpen)});document.addEventListener("keydown",function(e){if(e.key==="Escape"&&nav.classList.contains("active")){setMenuOpen(false)}});document.addEventListener("keydown",function(e){if(e.key!=="Tab"||!nav.classList.contains("active"))return;if(navLinks.length===0)return;const first=navLinks[0];const last=navLinks[navLinks.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}});document.addEventListener("click",function(e){if(nav.classList.contains("active")&&!nav.contains(e.target)&&!toggle.contains(e.target)){setMenuOpen(false)}})}function readCopy(){const out={};const hosts=document.querySelectorAll("[data-copy-set]");hosts.forEach(function(host){host.querySelectorAll("[data-copy]").forEach(function(el){const k=el.getAttribute("data-copy");if(k)out[k]=el.textContent})});return out}const COPY=readCopy();function copy(key,fallback){const v=COPY[key];return v!==undefined&&v!==null&&v!==""?v:fallback}const orderForm=document.querySelector(".order-form");if(orderForm){const status=orderForm.querySelector("#form-status");function setStatus(message,kind){if(!status)return;status.textContent=message||"";status.className="form-status"+(kind?" form-status-"+kind:"")}orderForm.addEventListener("submit",function(e){const required=orderForm.querySelectorAll("[required]");const errors=[];let firstError=null;required.forEach(function(field){if(!field.value.trim()){field.classList.add("error");field.setAttribute("aria-invalid","true");const label=orderForm.querySelector('label[for="'+field.id+'"]');const name=label?label.textContent.replace(/\*/g,"").trim():field.name;errors.push(copy("required","{field} is required").replace("{field}",name));if(!firstError)firstError=field}else{field.classList.remove("error");field.removeAttribute("aria-invalid")}});const emailField=orderForm.querySelector('[type="email"]');if(emailField&&emailField.value&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emailField.value)){emailField.classList.add("error");emailField.setAttribute("aria-invalid","true");errors.push(copy("invalidEmail","Please enter a valid email address"));if(!firstError)firstError=emailField}if(errors.length>0){e.preventDefault();setStatus(copy("errorPrefix","Please fix the following: ")+errors.join(copy("errorSeparator","; ")),"error");if(firstError){firstError.focus();firstError.scrollIntoView({behavior:"smooth",block:"center"})}}else{const d=new Date;const pad=function(n){return String(n).padStart(2,"0")};const stamp=d.getFullYear()+pad(d.getMonth()+1)+pad(d.getDate());const rand=Math.floor(Math.random()*1679616).toString(36).toUpperCase().padStart(4,"0");const refId="WA-"+stamp+"-"+rand;let refInput=orderForm.querySelector('input[name="reference_id"]');if(!refInput){refInput=document.createElement("input");refInput.type="hidden";refInput.name="reference_id";orderForm.appendChild(refInput)}refInput.value=refId;setStatus(copy("sending","Sending your request…"),"sending");const btn=orderForm.querySelector('[type="submit"]');if(btn){btn.disabled=true;btn.textContent=copy("sendingButton","Sending…")}try{sessionStorage.setItem("wa_ref_id",refId)}catch(e){}}});orderForm.querySelectorAll("input, select, textarea").forEach(function(field){field.addEventListener("input",function(){field.classList.remove("error");field.removeAttribute("aria-invalid");if(status&&status.classList.contains("form-status-error")){setStatus("",null)}})})}const refSlot=document.getElementById("reference-id-slot");if(refSlot){const params=new URLSearchParams(window.location.search);const fromQuery=params.get("id");const status=params.get("status");let fromSession=null;try{fromSession=sessionStorage.getItem("wa_ref_id")}catch(e){}const ref=(fromQuery||fromSession||"").toUpperCase();if(ref&&/^WA-\d{8}-[A-Z0-9]{4}$/.test(ref)){refSlot.textContent=ref;const copyBtn=document.getElementById("reference-copy");if(copyBtn){copyBtn.hidden=false;copyBtn.addEventListener("click",function(){navigator.clipboard.writeText(ref).then(function(){const orig=copyBtn.textContent;copyBtn.textContent=copy("copied","✓ Copied");setTimeout(function(){copyBtn.textContent=orig},2e3)}).catch(function(){})})}const mailto=document.getElementById("pending-mailto");if(mailto){mailto.href="mailto:order@weddingai.video?subject="+encodeURIComponent(copy("followupSubject","Follow-up on my quote {ref}").replace("{ref}",ref))+"&body="+encodeURIComponent(copy("followupBody","Hi,\n\nFollowing up on my quote request {ref}. I haven't received a confirmation email yet.\n\nThanks!").replace("{ref}",ref))}if(status==="pending"){const notice=document.getElementById("pending-notice");if(notice)notice.hidden=false;const icon=document.getElementById("success-icon");if(icon)icon.textContent="⏳";const headline=document.getElementById("success-headline");if(headline)headline.textContent=copy("pendingHeadline","We've Got Your Request");const summary=document.getElementById("success-summary");if(summary)summary.textContent=copy("pendingSummary","Your details are saved and our team will follow up within 24 hours. The automatic confirmation email didn't send on the first try — no action needed from you.")}try{sessionStorage.removeItem("wa_ref_id")}catch(e){}}}/* Cookie banner moved to js/cookie-consent.js (2026-11-02): the hard-coded English copy here overrode the localized one on all 10 non-English sites. */try{var year=(new Date).getFullYear();document.querySelectorAll('[data-i18n*="_weddingai_video_all_rights_reserve"]').forEach(function(el){el.textContent=el.textContent.replace(/\b\d{4}\b/,String(year))})}catch(e){}})();